create extension if not exists dblink;
begin;
select plan(10);
select dblink_connect('linkrace', format('dbname=%s user=%s password=postgres host=%s port=%s', current_database(), current_user, coalesce(host(inet_server_addr()), 'supabase_db_pmo-portal'), coalesce(inet_server_port(),5432)));
select dblink_exec('linkrace', $q$
 delete from platform_operators where user_id='39010000-0000-0000-0000-000000000012';
 delete from external_project_bindings where org_id='39010000-0000-0000-0000-000000000001';
 delete from projects where org_id='39010000-0000-0000-0000-000000000001';
 delete from profiles where org_id='39010000-0000-0000-0000-000000000001';
 delete from organizations where id='39010000-0000-0000-0000-000000000001';
 delete from auth.users where id in ('39010000-0000-0000-0000-000000000011','39010000-0000-0000-0000-000000000012');
 insert into organizations(id,name) values ('39010000-0000-0000-0000-000000000001','Link race');
 insert into auth.users(id) values ('39010000-0000-0000-0000-000000000011');
 insert into profiles(id,org_id,full_name,email,role,status) values ('39010000-0000-0000-0000-000000000011','39010000-0000-0000-0000-000000000001','Link actor','link-race@example.invalid','Admin','active');
 insert into auth.users(id) values ('39010000-0000-0000-0000-000000000012');
 insert into profiles(id,org_id,full_name,email,role,status) values ('39010000-0000-0000-0000-000000000012','39010000-0000-0000-0000-000000000001','Operator','link-operator-race@example.invalid','Finance','active');
 insert into platform_operators(user_id) values ('39010000-0000-0000-0000-000000000012');
 insert into projects(id,org_id,name,status) values ('39010000-0000-0000-0000-000000000021','39010000-0000-0000-0000-000000000001','Link project','Ongoing Project');
 insert into projects(id,org_id,name,status) values ('39010000-0000-0000-0000-000000000022','39010000-0000-0000-0000-000000000001','Another project','Ongoing Project');
 insert into external_org_bindings(org_id,external_tier,site_url,status,secret_ref,config) values ('39010000-0000-0000-0000-000000000001','erpnext','https://integration.example.test','active','','{}');
$q$);
select dblink_exec('linkrace','begin');
select dblink_exec('linkrace', $$update profiles set status='disabled' where id='39010000-0000-0000-0000-000000000011'$$);
set local lock_timeout='500ms';
set local role service_role;
set local request.jwt.claims = '{"role":"service_role"}';
select throws_ok($$select link_external_company('39010000-0000-0000-0000-000000000001','39010000-0000-0000-0000-000000000011','Acme','https://integration.example.test')$$,'55P03',null,'link waits for concurrent standing change');
reset role;
select dblink_exec('linkrace','commit');
set local role service_role;
select throws_ok($$select link_external_company('39010000-0000-0000-0000-000000000001','39010000-0000-0000-0000-000000000011','Acme','https://integration.example.test')$$,'42501',null,'committed standing change prevents company link');
select is((select config->>'company' from external_org_bindings where org_id='39010000-0000-0000-0000-000000000001'),null,'company remains unchanged');
reset role;
select dblink_exec('linkrace', $$update profiles set status='active' where id='39010000-0000-0000-0000-000000000011'$$);
select dblink_exec('linkrace', 'begin');
select dblink_exec('linkrace', 'set local role service_role');
select dblink_exec('linkrace', $q$set local request.jwt.claims = '{"role":"service_role"}'$q$);
select is((select result from dblink('linkrace', $$select link_external_company('39010000-0000-0000-0000-000000000001','39010000-0000-0000-0000-000000000012','Operator Company','https://integration.example.test')$$) as t(result boolean)),true,'operator company link acquires authority');
select is((select result from dblink('linkrace', $$select link_external_project('39010000-0000-0000-0000-000000000001','39010000-0000-0000-0000-000000000012','39010000-0000-0000-0000-000000000021','operator-list','{}') is not null$$) as t(result boolean)),true,'operator link acquires authority');
select throws_ok($$do $block$ begin delete from platform_operators where user_id='39010000-0000-0000-0000-000000000012'; raise exception 'revocation completed'; end $block$ $$,'55P03',null,'operator revocation waits for link transaction');
select dblink_exec('linkrace', 'commit');
select dblink_exec('linkrace', $$delete from platform_operators where user_id='39010000-0000-0000-0000-000000000012'$$);
set local role service_role;
select throws_ok($$select link_external_company('39010000-0000-0000-0000-000000000001','39010000-0000-0000-0000-000000000012','Denied','https://integration.example.test')$$,'42501',null,'committed operator revocation prevents company link');
select throws_ok($$select link_external_project('39010000-0000-0000-0000-000000000001','39010000-0000-0000-0000-000000000012','39010000-0000-0000-0000-000000000022','denied','{}')$$,'42501',null,'committed operator revocation prevents project link');
select is((select count(*)::integer from external_project_bindings where org_id='39010000-0000-0000-0000-000000000001'),1,'revoked operator adds no project link');
select ok(link_external_company('39010000-0000-0000-0000-000000000001','39010000-0000-0000-0000-000000000011','Acme','https://integration.example.test'),'active actor links after standing restored');
reset role;
select * from finish();
rollback;
select dblink_exec('linkrace', $$delete from external_project_bindings where org_id='39010000-0000-0000-0000-000000000001'; delete from projects where org_id='39010000-0000-0000-0000-000000000001'; delete from profiles where org_id='39010000-0000-0000-0000-000000000001'; delete from organizations where id='39010000-0000-0000-0000-000000000001'; delete from auth.users where id in ('39010000-0000-0000-0000-000000000011','39010000-0000-0000-0000-000000000012')$$);
select dblink_disconnect('linkrace');
drop extension if exists dblink;
